import{_ as o,o as i,c as t,a0 as l}from"./chunks/framework.DUAiDAGh.js";const p=JSON.parse('{"title":"VitePress + GitHub Actions 部署踩坑笔记","description":"","frontmatter":{},"headers":[],"relativePath":"archive/notes/vitepress-github-deploy.md","filePath":"archive/notes/vitepress-github-deploy.md"}'),s={name:"archive/notes/vitepress-github-deploy.md"};function a(r,e,c,n,d,g){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="vitepress-github-actions-部署踩坑笔记" tabindex="-1">VitePress + GitHub Actions 部署踩坑笔记 <a class="header-anchor" href="#vitepress-github-actions-部署踩坑笔记" aria-label="Permalink to &quot;VitePress + GitHub Actions 部署踩坑笔记&quot;">​</a></h1><blockquote><p>记录本次博客部署遇到的所有问题、原因与解决方案</p></blockquote><h2 id="一、构建阶段-actions-执行报错" tabindex="-1">一、构建阶段（Actions 执行报错） <a class="header-anchor" href="#一、构建阶段-actions-执行报错" aria-label="Permalink to &quot;一、构建阶段（Actions 执行报错）&quot;">​</a></h2><ol><li><strong>exit code 127：vitepress 命令找不到</strong></li></ol><ul><li>原因：只在电脑全局装了vitepress，<strong>没有写入package.json依赖</strong>，GitHub服务器执行<code>npm install</code>不会自动下载。</li><li>解决：本地执行 <code>npm install vitepress --save</code>，把依赖写入<code>package.json</code>和<code>package-lock.json</code>，提交到仓库；workflow脚本改用<code>npx vitepress build docs</code>调用。</li></ul><ol start="2"><li><strong>PowerShell 无法运行npm.ps1</strong></li></ol><ul><li>原因：Windows默认PowerShell执行策略阻止脚本。</li><li>解决：改用CMD终端操作，或者管理员权限修改PowerShell执行策略<code>Set-ExecutionPolicy RemoteSigned</code>。</li></ul><h2 id="二、git推送冲突问题" tabindex="-1">二、Git推送冲突问题 <a class="header-anchor" href="#二、git推送冲突问题" aria-label="Permalink to &quot;二、Git推送冲突问题&quot;">​</a></h2><ol start="3"><li><strong>rejected main -&gt; main (fetch first) 推送被拒绝</strong></li></ol><ul><li>原因：网页端手动新增/修改了仓库文件，<strong>远程代码版本比本地新</strong>，本地缺少远程的改动。</li><li>解决：先<code>git pull origin main</code>拉取远程代码合并，再提交推送。</li></ul><ol start="4"><li><strong>MERGE_HEAD exists 合并卡住</strong></li></ol><ul><li>原因：上一次<code>git pull</code>合并中断，Git处于未完成合并状态，不能继续pull/push。</li><li>解决：终止未完成合并 <code>git merge --abort</code>，再重新拉取代码。</li></ul><blockquote><p>额外避坑提醒：不要把打包产物<code>docs/.vitepress/dist/</code>提交到Git，新建<code>.gitignore</code>忽略该目录，否则仓库臃肿、极易产生文件冲突。</p></blockquote><h2 id="三、github-pages-网站访问阶段" tabindex="-1">三、GitHub Pages 网站访问阶段 <a class="header-anchor" href="#三、github-pages-网站访问阶段" aria-label="Permalink to &quot;三、GitHub Pages 网站访问阶段&quot;">​</a></h2><ol start="5"><li><strong>访问网页404</strong></li></ol><ul><li>原因1：Pages分支配置不对，没有选择<code>gh-pages</code>分支、根目录<code>/ (root)</code>。</li><li>原因2：Actions部署还没完成，保存Pages设置后需要等待1~3分钟。</li><li>解决：仓库Settings → Pages，设置Source为<code>Deploy from a branch</code>，分支选<code>gh-pages</code>，文件夹<code>/ (root)</code>，保存后等待。</li></ul><ol start="6"><li><strong>页面空白 / CSS、图片、链接404（资源加载失败）</strong></li></ol><ul><li>原因：VitePress配置<code>base</code>路径写错。仓库不是用户名仓库（<code>xxx.github.io</code>），项目仓库必须配置base。</li><li>解决：<code>docs/.vitepress/config.js</code>添加 <code>base: &#39;/My-blog/&#39;</code>，<strong>前后斜杠不能省略</strong>，修改后提交代码触发重新部署。</li></ul><ol start="7"><li><strong>自定义域名输入框</strong></li></ol><ul><li>作用：仅用于绑定你自己购买的域名；<strong>使用免费github.io地址时，这里留空，不用填写</strong>。</li></ul><h2 id="四、快速自查清单-以后部署前直接核对" tabindex="-1">四、快速自查清单（以后部署前直接核对） <a class="header-anchor" href="#四、快速自查清单-以后部署前直接核对" aria-label="Permalink to &quot;四、快速自查清单（以后部署前直接核对）&quot;">​</a></h2><ol><li>package.json是否包含vitepress依赖 ✅</li><li>workflow脚本使用npx调用构建命令 ✅</li><li>Git推送前：先pull同步远程代码，无未完成合并 ✅</li><li>.gitignore忽略node_modules、dist打包目录 ✅</li><li>vitepress config配置正确base路径 ✅</li><li>GitHub Pages：分支gh-pages，目录root ✅</li><li>部署成功后等待几分钟再访问网站 ✅</li></ol>',22)])])}const h=o(s,[["render",a]]);export{p as __pageData,h as default};
